 function categoryTest(table){const active=table.filter(r=>r.reduce((s,v)=>s+v,0)>0),cols=table[0].map((_,j)=>active.reduce((s,r)=>s+r[j],0)).map((v,j)=>v?j:-1).filter(j=>j>=0),t=active.map(r=>cols.map(j=>r[j])),rs=t.map(r=>r.reduce((s,v)=>s+v,0)),cs=cols.map((_,j)=>t.reduce((s,r)=>s+r[j],0)),n=rs.reduce((s,v)=>s+v,0);if(t.length<2||cols.length<2)return {p:null,statistic:null,effect:null,method:'Not estimable: no variation in one factor',expectedMinimum:null};let chi=0,expected=[];for(let i=0;i<t.length;i++)for(let j=0;j<cols.length;j++){const e=rs[i]*cs[j]/n;expected.push(e);chi+=(t[i][j]-e)**2/e;}const effect=Math.sqrt(chi/(n*Math.min(t.length-1,cols.length-1))),logP=m=>-m.flat().reduce((v,x)=>v+logGamma(x+1),0);if(cols.length===2&&t.length===2)return {p:fisher(...t.flat()),statistic:null,effect,method:'Two-sided Fisher exact',expectedMinimum:Math.min(...expected)};
 if(cols.length===2){const observed=logP(t),max=cs[0];let total=0,extreme=0;function walk(i,left,current){if(i===rs.length-1){if(left<0||left>rs[i])return;const m=[...current,[left,rs[i]-left]],lp=logP(m),weight=Math.exp(lp);total+=weight;if(lp<=observed+1e-9)extreme+=weight;return;}for(let v=Math.max(0,left-rs.slice(i+1).reduce((a,b)=>a+b,0));v<=Math.min(rs[i],left);v++)walk(i+1,left-v,[...current,[v,rs[i]-v]]);}walk(0,max,[]);return {p:extreme/total,statistic:null,effect,method:'Fisher–Freeman–Halton exact fixed-margin test',expectedMinimum:Math.min(...expected)};}
 const labels=cs.flatMap((c,j)=>Array(c).fill(j)),obs=logP(t),B=9999;let extreme=0;for(let b=0;b<B;b++){const lab=[...labels];for(let i=lab.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[lab[i],lab[j]]=[lab[j],lab[i]];}let k=0;const m=rs.map(size=>{const r=Array(cols.length).fill(0);for(let j=0;j<size;j++)r[lab[k++]]++;return r;});if(logP(m)<=obs+1e-9)extreme++;}const pv=(extreme+1)/(B+1);return {p:pv,statistic:null,effect,method:'Fisher–Freeman–Halton Monte Carlo fixed-margin test; 9,999 permutations',mcSE:Math.sqrt(pv*(1-pv)/(B+1)),expectedMinimum:Math.min(...expected)};
 }
 const clinicalSigns=[['Right iliac fossa tenderness',r=>[1,2].includes(r.tendernessRIF)?r.tendernessRIF===1?1:0:null,true],['Rebound tenderness',r=>[1,2].includes(r.reboundtenderness)?r.reboundtenderness===1?1:0:null,true],['Migratory abdominal pain',r=>[1,2].includes(r.migratory)?r.migratory===1?1:0:null,true],['Abdominal pain',r=>[1,2].includes(r.abdominal_pain)?r.abdominal_pain===1?1:0:null,true],...[[1,'Pointing sign'],[2,"Rovsing's sign"],[3,'Psoas sign'],[4,'Obturator sign'],[5,'Generalised tenderness']].map(([code,name])=>[name,r=>r.signs===code?1:null,false])];
 function categoricalTable(field,grouping,levels,groups){const r=rows.filter(x=>field(x)!==null&&grouping(x)!==null),matrix=levels.map((_,i)=>groups.map((_,j)=>r.filter(x=>field(x)===i+1&&grouping(x)===j).length));return {r,matrix,test:categoryTest(matrix)};}
