  if(r.log&&!Array.isArray(r.log)&&r.log.method&&num(r.log.p))evidence.push(`${r.log.method}: ${formatP(r.log.p)}${num(r.log.effect)?'; Cramér V='+f(r.log.effect):''}. ${r.log.p<.05?'The unadjusted comparison provides evidence of association at the retained 5% level.':'The comparison does not meet the retained 5% criterion; this does not establish equivalence.'}`);
  return context+' '+evidence.join(' ')+' '+(r.interpretation||'An additional substantive conclusion is unavailable.');
