 // Presentation audit: uses only stored estimates/counts; does not select or run tests.
 function reportingStandard(key,r){
  r.notes=[...r.notes,`Loaded records: ${rows.length}; result-level analysis n: ${r.n}. Row-specific denominators take precedence where shown.`, 'CI = confidence interval; SD = standard deviation; Q1–Q3 = first to third quartile (IQR limits); n = number of observations. Not estimable/Not estimated identifies unavailable evidence; Not applicable identifies an irrelevant field.'];
  const context=JSON.stringify([r.headers,r.methods,r.figure,r.rows.map(row=>row[0])]);
  if(/AUC|ROC|PPV|NPV|LR[+−]|Sensitivity \(|Specificity \(/i.test(context))r.notes.push('ROC = receiver operating characteristic; AUC = area under the ROC curve; TP/TN/FP/FN = true positive/true negative/false positive/false negative; PPV/NPV = positive/negative predictive value; LR+/LR− = positive/negative likelihood ratio. Sensitivity denominator = TP+FN; specificity = TN+FP; PPV = TP+FP; NPV = TN+FN; accuracy = all classified cases.');
  if(/MAS|hsCRP|AIR|PCV/.test(context))r.notes.push('MAS = Modified Alvarado Score; hsCRP = high-sensitivity C-reactive protein; AIR = Appendicitis Inflammatory Response score; PCV = packed cell volume. Retained units and clinical definitions require verification against the study protocol.');
  if(r.headers.some(h=>/p$|p-value/i.test(h))||r.log?.mann||Array.isArray(r.log)&&r.log.some(x=>num(x.p))||r.log?.method&&num(r.log.p))r.notes.push('Retained reporting convention α = 0.05. P-values are displayed to three decimals, or <0.001 when justified by the calculated value; unrounded inferential values remain in the calculation log where available. Statistical evidence alone does not establish clinical importance. Multiplicity treatment is stated in the methods; unadjusted exploratory comparisons require cautious interpretation.');
  if(r.log?.mann){const g=r.log,names=g.names||( /^(s2_|cost_)/.test(key)?['Complicated','Simple']:key.endsWith('histology')?['Histology-positive','Histology-negative']:key.endsWith('severity')?['Complicated','Simple']:['Recorded complication','Explicit none']);
   for(const [i,stats] of [g.a,g.b].entries())r.notes.push(`${names[i]}: n=${stats.n}; mean (SD) ${f(stats.mean)} (${f(stats.sd)}); median (Q1–Q3) ${f(stats.median)} (${f(stats.q1)}–${f(stats.q3)}); observed range ${f(stats.minimum)}–${f(stats.maximum)}. Units are those of the measured variable in the title/source notes.`);
   r.notes.push('The retained primary/sensitivity label uses sample size and skewness as a heuristic; it does not establish independence, distributional assumptions or protocol approval. Test choice/prespecification remains a methodological review item. Rank-biserial intervals are percentile bootstrap; the mean-difference interval is Welch-based; the median-difference interval is percentile bootstrap.');
  }
  if(/^(d1_|db_)/.test(key)&&r.log?.strategies){const ss=r.log.strategies;
   if(key.endsWith('_predictive')){r.headers.push('Threshold / evaluation','PPV denominator','NPV denominator','All classified n');r.rows.forEach((row,i)=>{const x=ss[i];row.push(x.threshold+' · '+(x.kind==='model'?'held-out exploratory model':'unfitted marker'),x.metrics.ppv.n,x.metrics.npv.n,x.metrics.n);});}
   if(key.endsWith('_calibration'))r.notes.push('These are prediction-performance results, not coefficient-inference results. Standard errors, coefficient/odds-ratio confidence intervals, likelihood-based coefficient tests and adjusted clinical effects are not calculated by this browser engine. No such results are inferred from held-out predictions.');
   r.notes.push('Reference standard: retained histology coding, with code 6 negative only under the stated reactive-lymphoid-hyperplasia assumption. The Objective 1 fixed-rule tables implement both required MAS + hs-CRP AND/OR analyses; legacy fitted probability outputs remain separate and are not clinical combination rules.');
  }
  if(r.kind==='figure'){
   const type=r.figure.type;r.notes.push('Figure sample size and axis units follow the actual plotted observations and stated source definitions.');
   if(type==='forest')r.notes.push('Points are available effect estimates; horizontal lines are available 95% intervals. Absent lines indicate unavailable intervals. Effects/intervals extending outside the axis range are flagged at the plotting boundary.');
   if(type==='box')r.notes.push('Box = Q1–Q3; centre line = median; whiskers = observed minimum–maximum, not 1.5×IQR fences. No outlier classification is implied.');
   if(type==='calibration')r.notes.push('Vertical error bars are 95% Wilson intervals for observed proportions; circle size reflects bin n.');
   if(type==='roc')r.notes.push('ROC axes range from 0 to 1; the diagonal is the no-discrimination reference. Curves are point estimates, without confidence bands. See the companion AUC table for available intervals.');
  }
  return r;
 }
 // Master strategy evaluation is separate from preserved diagnostic outputs. Patient predictions
 // stay in this worker; only aggregate summaries/paired discordance counts are returned.
